import { Amplify } from 'aws-amplify';
import { generateClient } from 'aws-amplify/data';
import type { Schema } from '../../amplify/data/resource';
import { normalize } from './storage';
import type { CloudAdapter } from './sync';

// amplify_outputs.json is generated by the Amplify build (or `npx ampx sandbox`).
// Without it the app runs in local-only mode, so `npm run dev` works with no AWS setup.
const outputs = Object.values(
  import.meta.glob<Record<string, unknown>>('../../amplify_outputs.json', { eager: true, import: 'default' }),
)[0];

export const cloudEnabled = !!outputs;
if (outputs) Amplify.configure(outputs);

export function createCloudAdapter(userId: string): CloudAdapter {
  const client = generateClient<Schema>();
  let exists = false;

  const check = (errors?: readonly { message: string }[]) => {
    if (errors?.length) throw new Error(errors[0].message);
  };

  return {
    async load() {
      const { data, errors } = await client.models.Progress.get({ id: userId });
      check(errors);
      if (!data) return null;
      exists = true;
      return normalize(typeof data.state === 'string' ? JSON.parse(data.state) : data.state);
    },
    async save(state) {
      const record = { id: userId, state: JSON.stringify(state), clientUpdatedAt: state.updatedAt };
      const write = (create: boolean) => (create ? client.models.Progress.create(record) : client.models.Progress.update(record));
      let { errors } = await write(!exists);
      // Our guess about whether the record exists was wrong (e.g. created from another device): try the other call.
      if (errors?.length) ({ errors } = await write(exists));
      check(errors);
      exists = true;
    },
  };
}
